const message = ($json.body.message || '').toLowerCase();
let reply = '';
let chips = [];

if (message.includes('mars') || message.includes('b.') || message.includes('b')) {
  reply = '🎉 **LUAR BIASA, TEPAT SEKALI!**
Jawabannya adalah **B. Mars** (warna merah berasal dari besi oksida/karat di tanahnya).

**+100 Poin untukmu!**

---

**Babak 2 (Sejarah & Komputasi):**
*Siapakah matematikawan dan ilmuwan komputer yang memecahkan kode Enigma pada Perang Dunia II?*';
  chips = ['Alan Turing', 'Charles Babbage', 'Ada Lovelace', 'John von Neumann'];
} else if (message.includes('turing')) {
  reply = '🏆 **BENAR LAGI!**
**Alan Turing** adalah tokoh kunci di Bletchley Park yang memecahkan mesin Enigma!

**Total Skor: 200 Poin!**

---

**Babak 3 (Geografi):**
*Danau terdalam di dunia yang menampung 20% air tawar tak beku di bumi adalah?*';
  chips = ['Danau Baikal', 'Danau Toba', 'Danau Victoria', 'Danau Superior'];
} else {
  reply = `Jawaban/Respons tercatat: "${$json.body.message}".

Mari lanjutkan ke tantangan kuis berikutnya! Pilih kategori yang ingin kamu taklukkan:`;
  chips = ['Sains & Antariksa', 'Sejarah Dunia', 'Teknologi & AI', 'Pop Culture & Film'];
}

return { json: { content: reply, chips: chips } };
